import { ReactNode } from 'react';
import { Card } from './Card';
import { cn } from './cn';

export interface StatCardProps {
  label: string;
  /** Valor grande, tipicamente um número. Renderizado em font-mono. */
  value: ReactNode;
  /** Delta curto ao lado do label, ex.: "+18%" ou "11 só IA". */
  delta?: string;
  /** 'up' colore o delta em --ok; 'neutral' em --tx3. */
  deltaTone?: 'up' | 'neutral';
  /** Linha de contexto abaixo do valor. */
  hint?: string;
  /** Pontos de uma sparkline em SVG (0–100 em x e y), opcional. */
  sparkline?: string; // path "d" já normalizado, ex. gerado por utils/sparkline.ts
}

/**
 * Card de KPI grande (4 por linha na Visão geral). Sempre:
 * label → valor (mono, 44px) → hint. Sparkline é decorativa e SEMPRE em --spark
 * (nunca na cor de acento) para não competir com o número.
 */
export function StatCard({ label, value, delta, deltaTone = 'neutral', hint, sparkline }: StatCardProps) {
  return (
    <Card className="flex min-h-[172px] flex-col p-6">
      <div className="flex items-center justify-between text-base font-medium text-tx2">
        <span>{label}</span>
        {delta && (
          <span className={cn('font-mono text-xs', deltaTone === 'up' ? 'text-ok' : 'text-tx3')}>
            {delta}
          </span>
        )}
      </div>
      <div className="mt-auto font-mono text-3xl font-medium leading-none tracking-tighter text-tx">
        {value}
      </div>
      {hint && <div className="mt-2 text-sm text-tx3">{hint}</div>}
      {sparkline && (
        <svg viewBox="0 0 200 28" preserveAspectRatio="none" className="mt-3.5 h-7 w-full">
          <path d={sparkline} stroke="var(--spark)" strokeWidth={1.5} fill="none" vectorEffect="non-scaling-stroke" />
        </svg>
      )}
    </Card>
  );
}
